curl -s "https://en.wikipedia.org/w/api.php?action=query&prop=revisions&rvprop=content&titles=Washington,_D.C.&format=json" 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
pages = data['query']['pages']
for p in pages.values():
    if 'revisions' in p:
        content = p['revisions'][0]['*']
        # Look for DC groundhog or Chuckaree
        if 'Chuckaree' in content or 'groundhog' in content.lower():
