            start = content.find('Chuckaree')
            if start == -1:
                start = content.lower().find('groundhog')
            print(content[start:start+5000])
        else:
            # Just print first relevant info about origin
            start = content.find('Origin')
            if start == -1:
                start = content.find('History')
            if start != -1 and start < 10000:
                print(content[start:start+3000])
" 2>&1 | head -100

