action_args.command:
curl -s "https://en.wikipedia.org/w/api.php?action=query&prop=revisions&rvprop=content&titles=Groundhog_Day&format=json" 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
pages = data['query']['pages']
for p in pages.values():
    if 'revisions' in p:
        content = p['revisions'][0]['*']
        # Look for regional celebrations section
        start = content.find('Regional')
        if start == -1:
            start = content.find('regional')
        if start == -1:
            start = content.lower().find('groundhog day')
            while start != -1:
                start = content.lower().find('groundhog day', start+1)
        # Print section with regional
        for keyword in ['Regional celebration', 'regional celebration', 'Other groundhog', 'Washington', 'DC groundhog']:
            idx = content.find(keyword)
            if idx != -1:
                print(content[max(0,idx-200):idx+2000])
                print('---BREAK---')
" 2>&1 | head -200

